    {writable ? (
      <form className="card" onSubmit={create}>
        <h2>{t('proj.new')}</h2>
        <ErrorBanner error={error} />
        <div className="form-grid">
          <Field label={t('common.name')}>{(p) => <input {...p} value={name} onChange={(e) => setName(e.target.value)} required />}</Field>

