// notification, until ctx ends. It reconnects after errors.
func Listen(ctx context.Context, db *pgxpool.Pool, chans []string, fn func(channel, payload string)) {
	for ctx.Err() == nil {
		err := listenOnce(ctx, db, chans, fn)
