                """{"name": "du_bao_thoi_tiet", "description": "tra ve du bao thoi tiet cho mot thanh fo. bo wa ket wa ku hon 24 h.", "inputSchema": {"type": "object", "properties": {"dau_vao": {"type": "string"}}}}"""
                continue
